/**
 * The verdict: output sections under a persistent "Generated by AI" notice, a report
 * action, a share card (watermark + deep link naming the sharer) captured with
 * react-native-view-shot and sent through the system share sheet, and, when the spec has
 * one, a one-to-one invite. share, share_first and invite_sent fire only for a completed
 * sheet on iOS; Android cannot report completion, so its events carry confirmed: false.
 */
import { router } from "expo-router";
import * as Sharing from "expo-sharing";
import { useEffect, useRef, useState } from "react";
import { Alert, Platform, Share, Text, View, type HostInstance } from "react-native";
import { captureRef } from "react-native-view-shot";
import { reportResult } from "../src/api";
import { distinctId, track } from "../src/analytics";
import { APP_EVENTS } from "../src/events";
import { shareOutcome } from "../src/growth";
import { inviteUrl, shareUrl } from "../src/links";
import { isEntitled } from "../src/purchases";
import { appUserId } from "../src/session";
import { useSpec } from "../src/spec";
import { getJson, KEYS, once, type StoredResult } from "../src/storage";
import { Body, Button, Card, LinkText, Notice, Screen, Title, useTheme } from "../src/ui";

const REPORT_REASONS = ["Harmful or offensive", "Inaccurate", "Something else"];

export default function Result() {
  const spec = useSpec();
  const t = useTheme();
  const card = useRef<HostInstance>(null);
  const [result, setResult] = useState<StoredResult | null>(null);
  const [entitled, setEntitled] = useState(true);
  const [sharing, setSharing] = useState(false);

  useEffect(() => {
    void getJson<StoredResult | null>(KEYS.lastResult, null).then(setResult);
    void isEntitled().then(setEntitled);
  }, []);

  if (!result) return null;
  const link = shareUrl(spec.share.deepLinkPath, result.id, distinctId());
  const lead = result.sections[0];
  const invite = spec.invite;

  /** iOS: React Native Share reports completion; Android: expo-sharing (files), which cannot. */
  async function openSheet(uri: string): Promise<string | null> {
    if (Platform.OS === "ios") return (await Share.share({ url: uri, message: spec.share.caption })).action;
    if (!(await Sharing.isAvailableAsync())) throw new Error("Sharing is not available on this device.");
    await Sharing.shareAsync(uri, { mimeType: "image/png", dialogTitle: spec.share.caption, UTI: "public.png" });
    return null;
  }

  async function share() {
    if (!card.current) return;
    setSharing(true);
    try {
      const uri = await captureRef(card, { format: "png", quality: 1, result: "tmpfile" });
      const { counted, confirmed } = shareOutcome(Platform.OS, await openSheet(uri));
      if (!counted) return;
      track(APP_EVENTS.share, { artifact: spec.share.artifact, method: "system_share_sheet", confirmed });
      if (await once(KEYS.shareFirst)) track(APP_EVENTS.shareFirst, { artifact: spec.share.artifact, confirmed });
    } catch (err) {
      Alert.alert("Couldn't share", err instanceof Error ? err.message : "Please try again.");
    } finally {
      setSharing(false);
    }
  }

  async function sendInvite() {
    if (!invite) return;
    const message = `${invite.prefilledMessage} ${inviteUrl(spec.share.deepLinkPath, distinctId())}`;
    const { action } = await Share.share({ message }).catch(() => ({ action: "dismissedAction" }));
    const { counted, confirmed } = shareOutcome(Platform.OS, action);
    if (counted) track(APP_EVENTS.inviteSent, { method: invite.method, confirmed });
  }

  function report() {
    Alert.alert("Report this result", "Tell us what is wrong. Reports are reviewed by a person.", [
      ...REPORT_REASONS.map((reason) => ({
        text: reason,
        onPress: () => {
          void reportResult(appUserId(), result?.id ?? "", reason)
            .then(() => Alert.alert("Thanks", "Your report was sent."))
            .catch(() => Alert.alert("Couldn't send", "Please try again or email support."));
        },
      })),
      { text: "Cancel", style: "cancel" as const },
    ]);
  }

  return (
    <Screen
      footer={
        <>
          <Button label="Share" onPress={() => void share()} busy={sharing} />
          {invite ? <Button label="Invite a friend" kind="secondary" onPress={() => void sendInvite()} /> : null}
          {!entitled && spec.paywall.placement === "after_first_value" ? (
            <Button label="Unlock everything" kind="secondary" onPress={() => router.push({ pathname: "/paywall", params: { placement: "after_first_value" } })} />
          ) : (
            <Button label="Try another" kind="secondary" onPress={() => router.replace("/home")} />
          )}
        </>
      }
    >
      <Notice text={`Generated by AI. ${spec.compliance.aiDisclosure}`} />
      {result.sections.map((s) => (
        <Card key={s.title}>
          <Body>{s.title}</Body>
          <Body muted>{s.body}</Body>
        </Card>
      ))}
      <LinkText label="Report this result" onPress={report} />
      <View ref={card} collapsable={false} style={{ borderRadius: 24, padding: 24, gap: 12, backgroundColor: t.primary, borderWidth: 3, borderColor: t.accent }}>
        <Title>{spec.share.cardHeadline}</Title>
        {lead ? (
          <>
            <Body>{lead.title}</Body>
            <Body muted>{lead.body.length > 220 ? `${lead.body.slice(0, 217)}…` : lead.body}</Body>
          </>
        ) : null}
        <Text style={{ color: t.text, opacity: 0.85, fontWeight: "700" }}>{spec.share.watermark}</Text>
        <Text style={{ color: t.text, opacity: 0.7, fontSize: 12 }}>{link}</Text>
        <Text style={{ color: t.text, opacity: 0.6, fontSize: 10 }}>Generated by AI</Text>
      </View>
    </Screen>
  );
}
